import{_ as e,o as a,c as o,a5 as r}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"ESM 单例","description":"1. 重点速览 • ESM 单例 ： import 的模块只执行一次，后续导入都复用同一份实例。 • 响应式 Store ： reactive({}) 充当轻量全局状态，无需 Pinia。 • 集中计算 ： watch(now, ...) 只注册一次，按时钟批量刷新所有 mark。","frontmatter":{"title":"ESM 单例","date":"2026-08-11T00:00:00.000Z","categories":["JavaScript 系统教程"],"tags":["JavaScript","前端","教程","OneNote","模块化与工程化"],"description":"1. 重点速览 • ESM 单例 ： import 的模块只执行一次，后续导入都复用同一份实例。 • 响应式 Store ： reactive({}) 充当轻量全局状态，无需 Pinia。 • 集中计算 ： watch(now, ...) 只注册一次，按时钟批量刷新所有 mark。","sidebarWeight":7,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/b-原生js/12-模块化编程/ESM 单例.md"},"headers":[],"relativePath":"posts/JavaScript系统教程/06-模块化与工程化/ESM 单例.md","filePath":"posts/JavaScript系统教程/06-模块化与工程化/ESM 单例.md"}'),s={name:"posts/JavaScript系统教程/06-模块化与工程化/ESM 单例.md"};function d(c,t,i,n,p,l){return a(),o("div",null,[...t[0]||(t[0]=[r('<div><h1 id="esm-单例" tabindex="-1">ESM 单例 <a class="header-anchor" href="#esm-单例" aria-label="Permalink to &quot;ESM 单例&quot;">​</a></h1><blockquote><p>本节目标：理解“ESM 单例”的核心思路，并能把它用于实际开发或面试表达。</p></blockquote><ol><li><p>重点速览 • <strong>ESM 单例</strong>：<code>import</code> 的模块只执行一次，后续导入都复用同一份实例。 • <strong>响应式 Store</strong>：<code>reactive({})</code> 充当轻量全局状态，无需 Pinia。 • <strong>集中计算</strong>：<code>watch(now, ...)</code> 只注册一次，按时钟批量刷新所有 market。 • <strong>Hook 只读接口</strong>：<code>useMarketState(symbolId)</code> 每次返回 <code>readonly(computed(...))</code>，组件感知但无法乱改。</p></li><li><p>详细拆解 2-1 模块单例机制 // useMarketState.ts const marketStates = reactive&lt;Record&lt;string, MarketState&gt;&gt;({}); // 这里在模块顶层 —— 初始化一次</p></li></ol><p>在任何组件里 <code>import { useMarketState } ...</code>，引擎保证： • 代码只跑第一次； • <code>marketStates</code>、<code>watch</code>、<code>holidaySet</code> 等只创建一份。</p><p>2-2 顶层响应式全局状态 const marketStates = reactive&lt;Record&lt;string, MarketState&gt;&gt;({});</p><ul><li>用对象索引 (<code>marketId</code>) 分区，天然隔离。</li><li>Vue3 响应式代理，组件读取时自动依赖收集。</li></ul><p>2-3 定时 watch 与计算逻辑 watch( now, (minute) =&gt; { for (const marketId of Object.keys(dynamicSessionMap)) { marketStates[marketId] = computeState(marketId, minute); } }, { immediate: true } );</p><p>• <code>now</code> 来自 <code>useMarketClock</code>（每分钟自增）。 • <strong>单 watch，多 market</strong>：一次遍历把所有市场状态更新完。 • 避免在每个组件里各自 setInterval。</p><p>2-4 Hook 封装 &amp; 组件使用 export function useMarketState(symbolId: string) { // 动态场景：直接用 symbolId 作为 marketId const state = computed(() =&gt; marketStates[symbolId]); return { state: readonly(state) }; }</p><ul><li>组件只拿到当前合约的视图，不感知全局实现细节。</li><li>任何组件卸载不影响 watch；复用高效。</li></ul><ol start="3"><li>最小可运行示例</li></ol><p>(1) useMarketClock.ts — 1 行核心 import { ref } from &#39;vue&#39;; export function useMarketClock() { const now = ref(dayjs()); setInterval(() =&gt; (now.value = dayjs()), 60_000); return { now }; }</p><p>(2) useMarketState.ts — 精简版 import { reactive, computed, readonly, watch } from &#39;vue&#39;; import { useMarketClock } from &#39;./useMarketClock&#39;; type MarketState = { isOpen: boolean }; const marketStates = reactive&lt;Record&lt;string, MarketState&gt;&gt;({}); const { now } = useMarketClock(); function computeState(id: string) { // ★ 真实逻辑可复杂，这里简写为“偶数分钟开市” return { isOpen: now.value.minute() % 2 === 0 }; } watch(now, () =&gt; { for (const id of Object.keys(marketStates)) marketStates[id] = computeState(id); }); export function useMarketState(id: string) { marketStates[id] ??= computeState(id); // 首次填充 const state = computed(() =&gt; marketStates[id]); return { state: readonly(state) }; }</p><p>(3) Component.vue &lt;script setup lang=&quot;ts&quot;&gt; import { useMarketState } from &#39;@/composables/useMarketState&#39;; const { state } = useMarketState(&#39;EURUSD&#39;); &lt;/script&gt; &lt;template&gt; &lt;div&gt;{{ state.isOpen ? &#39;OPEN&#39; : &#39;CLOSED&#39; }}&lt;/div&gt; &lt;/template&gt;</p><p>👉 复制三文件即可运行，验证「单 watch 全局刷新」+「多组件共享」效果。 4. 常见问题 &amp; 进阶</p><table tabindex="0"><thead><tr><th>场景</th><th>风险</th><th>解决方案</th></tr></thead><tbody><tr><td>HMR 开发热更新</td><td>旧 watch 未注销</td><td><code>import.meta.hot.dispose(stopWatch)</code></td></tr><tr><td>SSR</td><td>同服务器跨请求数据串联</td><td>把全局状态放到 per-request 上下文</td></tr><tr><td>多时钟源</td><td>需要多份计算循环</td><td>将 clock 和 state 封装到类/Pinia store，实例化多份</td></tr></tbody></table><p>参考 • Vue 官方文档「组合式 API – 响应式基础」 • ES Modules Loading – WHATWG Spec • HMR 处理示例 &lt;<a href="https://vitejs.dev/guide/api-hmr.html" target="_blank" rel="noreferrer">https://vitejs.dev/guide/api-hmr.html</a>&gt;</p></div>',1)])])}const S=e(s,[["render",d]]);export{u as __pageData,S as default};
